    'منطقة المدينة المنورة',
    'منطقة الرياض',
    'منطقة القصيم',
    'منطقة عسير',
    'منطقة جازان',
    'منطقة تبوك',
    'منطقة مكة المكرمة',
    'منطقة حائل',
    'المنطقة الشرقية',
    'منطقة الجوف',
    'منطقة نجران',
  ];

  MapShellController? _mapController;
  String? _expandedRegion;
  final Map<String, TourismLandmark> _annotationLandmarkMap = {};

  Future<void> _loadMarkers(MapShellController controller) async {
    final validLandmarks = _landmarks
        .where((l) => l.latitude > 0.0 && l.longitude > 0.0)
        .toList();

    if (kIsWeb) {
      final webUrl = 'assets/${AppAssets.markerIcon}';
      final batchList = validLandmarks
          .map((landmark) => {
                'id': '${landmark.latitude}_${landmark.longitude}',
                'lat': landmark.latitude,
                'lng': landmark.longitude,
                'iconUrl': webUrl,
              })
          .toList();

      final landmarkMap = {
        for (final landmark in validLandmarks)
          '${landmark.latitude}_${landmark.longitude}': landmark
      };

      controller.setWebMarkersBatch(jsonEncode(batchList), (markerId) {
        final landmark = landmarkMap[markerId];
        if (landmark != null) {
          _showLandmark(landmark);
        }
      });
      return;
    }

    final manager = controller.pointAnnotationManager;
    if (manager == null) return;

    try {
      final ByteData byteData = await rootBundle.load(AppAssets.markerIcon);
      final Uint8List imageBytes = byteData.buffer.asUint8List();

      final optionsList = validLandmarks.map((landmark) {
        return PointAnnotationOptions(
          geometry: Point(
              coordinates: Position(landmark.longitude, landmark.latitude)),
          image: imageBytes,
          iconSize: 0.25,
        );
      }).toList();

      final annotations = await manager.createMulti(optionsList);
      for (int i = 0;
          i < annotations.length && i < validLandmarks.length;
          i++) {
        final ann = annotations[i];
        if (ann != null) {
          _annotationLandmarkMap[ann.id] = validLandmarks[i];
        }
      }

      manager.addOnPointAnnotationClickListener(
        AppPointAnnotationClickListener((annotation) {
          final landmark = _annotationLandmarkMap[annotation.id];
          if (landmark != null) {
            _showLandmark(landmark);
          }
        }),
      );
    } catch (e) {
      debugPrint('Error creating tourism annotations: $e');
    }
  }

  void _showLandmark(TourismLandmark landmark) {
    if (landmark.latitude > 0.0 &&
        landmark.longitude > 0.0 &&
        _mapController != null) {
      _mapController!.flyTo(
        latitude: landmark.latitude,
        longitude: landmark.longitude,
        zoom: 10.0,
      );
    }
    AppPopupDialog.show(
      context,
      title: landmark.title,
      description: landmark.description,
      imageAsset: landmark.imageAsset,
    );
  }

  void _showIntroBrief() {
    AppBriefDialog.show(
      context,
      title: 'السياحة والآثار',
      description:
          'ظهر مفهوم السياحة الجيولوجية للمرة الأولى في 1995م من قِبل توماس هوز، لتشكّل وسيلة لتعزيز الحفظ الجغرافي وفهم التراث، كما تعزز المسؤولية البيئية والاجتماعية والاستدامة. السياحة الجيولوجية الآن هي جزء من السياحة الجغرافية كما تركّز على السمات غير الحيوية مثل التراكيب الجيولوجية من فوالق وطيات وعلى فوهات البراكين الخامدة ومجموعة كبيرة جداً من الأحافير من كل الأزمنة الجيولوجية. إن المنظور (الجغرافي) يرى السياحة الجيولوجية على أنها سياحة مستدامة. في المقابل، يرى المنظور (الجيولوجي) أنها شكل من أشكال السياحة التقليدية. مع نمو السياحة الجيولوجية، نشأ مخطط تصنيف للخصائص الجيولوجية، وأخذ في الاعتبار القيمة الجيولوجية للموقع وعكس تصورات وتقييمات السائحين.\nتحظى المملكة بالعديد من المواقع الجيولوجية في جميع مناطقها ومدنها، بسبب التنوع الجغرافي لها، وبدأ استغلال هذه الطبيعة لتكون جزءاً مهماً من التنمية السياحية. إن السياحة الجيولوجية في المملكة تمتاز بمساحتها الشاسعة وطبيعتها المتنوعة من صحراء وبحار وجبال وأودية وسواحل، كل ذلك مكّن السائحين من الاستمتاع بتجارب استكشافية لمعالم يعود تاريخها إلى آلاف السنين. أن تنوع السجلات الصخرية يعد إرثاً جيولوجياً يمكن وضعه على خريطة المملكة السياحية، وهذا يتطلب إنشاء متنزهات جيولوجية على قمم الجبال وبين أوديتها لتوعية الجمهور وتثقيفه بأهمية السياحة الجيولوجية. أن المملكة حباها الله بموقع جغرافي استراتيجي متميز على مساحة قرابة مليوني كيلو متر مربع، إضافة إلى تنوع كبير وفريد في طبيعتها الجيولوجية، وتضاريسها؛ فبيئتها الجيولوجية تختلف من مكانٍ إلى مكان، ما بين صحراوية وجبلية وساحلية، وأراضٍ رطبة يجب استغلالها، والعمل على تقييمها، ما يعزز أهمية إدراجها ضمن خطط تنويع روافد الاقتصاد الوطني كوجهات سياحية تسهم في جذب السُياح والهواة، وفقاً لمستهدفات رؤية 2030. تمتاز المملكة بطول ساحلها الغربي المطل على البحر الأحمر، ويبلغ عدد الجزر التي تتبع لها جغرافياً نحو 1150 جزيرة، مختلفة في النوع وفي المساحة، كما بلغ عدد الجزر المطلة على الخليج العربي نحو 150 جزيرة، تختلف في أنواعها؛ منها الجزر الرملية والبركانية والجزر الصخرية مرجانية التكوين. يوجد آلاف المعالم من كهوف وصخور نارية وأحافير تعود إلى مختلف العصور مثل الأشجار المتحجرة، وطبعات أقدام الديناصورات، والأمونيات، وأصداف الرخويات، فهناك جبل طويق الجوراسي العمر، الذي تكون ما بين 135 إلى 180 مليون سنة ماضية، ويمتد إلى أكثر من ألف كيلو متر من شمال الزلفي إلى جنوب شرق وادي الدواسر. وفي الشمال، يقع موقع «غار العمة» في مدينة القريات والعيون الكبريتية في قرية كاف، وقرية عين الحواس وأماكن استخراج الملح في القريات التي يمكن تطويرها سياحياً، إضافة إلى العيون الحارة بالخوبة جنوب شرق مدينة جازان بمسافة 70 كم، وعلى ارتفاع 160م من منسوب سطح البحر، ويشتمل الموقع على عدد أربعة عيون، وتتراوح درجات حرارة المياه الخارجة منها بين 58 و75 درجة مئوية. هناك المناطق البركانية المُسمَّاة بالحرات، وتنتشر عليها مئات البراكين الخامدة، وتأتي كالتالي من الجنوب إلى الشمال: حرة السراة، البرك، البقوم، النواصف، هادان، الكشب، رهط، حلة أبو نار، خيبر، العويرض، الشامة والحماد. حرة رهط وحدها فيها نحو 700 مخروط بركاني، كما أنها صُنفت من قبل الهيئة العليا للسياحة، كأول متنزه جيولوجي في المملكة يمثّل متحفاً بركانياً مفتوحاً . السياحة الجيولوجية في المملكة تشمل أيضاً الأشكال الجيومورفولوجية لصخور الميوسين لجبال برقاء الركبان غرب الأحساء، والمغارات، إضافة إلى رمال النفوذ الكبير شمال حائل والربع الخالي الذي يعتبر أكبر جسم رملي متصل في العالم. وفي جنوب غرب العبيلة، يقع أحد مواقع ارتطام نيزك بالأرض تُسمّى «الحديدة»، فضلاً عن مناطق الرمال الأخرى مثل الجافورة والدهناء، وتتمتع المملكة بظاهرة ورود الصحراء شمال بقيق، والأشجار المتحجرة في القصيم التي تعود للعصر البرمي منذ أكثر من 240 مليون سنة، وكذلك الموجودة شرق الرياض التي تعود إلى لعصر الطباشيري لأكثر من 70 مليون سنة. إن المملكة متحف جيولوجي مفتوح تكشف فيه الصخور عن معظم العصور الجيولوجية، بدءاً من صخور القاعدة التي تشكل صخور الدرع العربي، تعلوها صخور دهر الحياة الظاهرة (حقبة الحياة القديمة والمتوسطة والحديثة) والتي يمتد عمرها من 550 مليون سنة حتى وقتنا الحاضر. في ظل وجود هذا المتحف الجيولوجي المكشوف على أراضي المملكة يمكن أن يُستغل كرافد مهم للاقتصاد، ومحور أساسي في رؤية 2030 كمصدر جديد من مصادر الدخل القومي، فهناك إمكانية لتأسيس الحدائق الجيولوجية، وهي الأراضي ذات مكونات جيولوجية فريدة، وبلغ عددها حتى الآن 54 حديقة حول العالم تنتشر في 17 بلداً. لا تقتصر الأهمية الاقتصادية للسياحة الجيولوجية كمصدر للدخل على السياحة الداخلية بل يمكن استغلالها كمصدر للعملة الصعبة من السياحة العلمية من جميع أنحاء العالم. هذا المتحف الجيولوجي يضم معالم متنوعة تشكلت بشكل طبيعي في طبقات الحجر الرملي والجيري، وكذلك تنوع المنكشفات الطبوغرافية المختلفة من أودية وجبال وكهوف وأحافير، ومواقع لمناجم تعدينية قديمة، وسهول وهضاب متميزة، وشواطئ منها صخرة الجمل في محافظة الوجه وهي عبارة عن تكون صخري تشكل بفعل عوامل التعرية من ملايين السنين، وكذلك صخرة التين في محافظة الوجه وهي تشكيل صخري من صخور الحجر الجيري تكون نتيجة لعوامل التعرية يشبه ثمرة التين، ووادي الديسة في محافظة تبوك المليء بالتشكيلات الصخرية، كما يمتاز بغطاء نباتي كثيف وعيون وينابيع مياه. إن المملكة أصبحت وجهة سياحية عالمية، حيث استفادت من اعتماد منظمة «اليونسكو» للمواقع السياحية الأثرية فيها، ما انعكس على القطاع باستقبال أكثر من 100 مليون سائح، وإضافة نحو 130 ألف غرفة فندقية لخدمة العدد المتزايد منهم. من المتوقع أن تخلق صناعة السياحة في المملكة أكثر من 1.6 مليون وظيفة جديدة بحلول عام 2030، ما يرفع مساهمة الصناعة في الناتج المحلي الإجمالي إلى 10 في المئة، ومن المتوقع أن ينمو إجمالي الإنفاق على السياحة الدولية بنسبة 82 في المئة إلى أكثر من 560 مليار ريال سعودي بحلول عام 2030. تعتبر صناعة السياحة في المملكة الآن في المرتبة الثانية الأسرع نمواً في العالم بالتزامن مع نمو الوافدين الدوليين في الربع الأول من 2023، مسجلة نمواً بنسبة 64 في المئة مقارنة بالربع الأول من 2019، كما وفرت المملكة أكثر من 836 ألف فرصة عمل جديدة على المستوى المحلي، ما رفع مساهمة السياحة في الناتج المحلي الإجمالي للمملكة إلى 5.3 في المئة.\nوباختصار فإن المملكة تجري تحولاً وطنياً كجزء من رؤية 2030، لتغيير المشهد محلياً ودولياً، ومنذ الانفتاح على السياحة في 2019، أقامت عرضاً تنافسياً يجمع بين الثقافة العربية الأصيلة وعرضاً ترفيهياً سريع الانتشار، ومع استمرارنا في التحول كوجهة، سنسعى دائماً للحفاظ على تراثنا والاحتفاء به، ودعوة العالم لتجربة كل ما تقدّمه المملكة مع الحفاظ على التزامنا بحماية المناظر الطبيعية وبيئتنا. \n\n\nأنه يمكن رؤية أمثلة على كيفية تحقيقنا لهذا الهدف في:\n•	الدرعية، إذ يخضع موقع التراث العالمي لليونسكو الذي يعود تاريخه إلى 300 عام لمخطط رئيسي بقيمة 50.6 مليار دولار مع التراث والتقاليد السعودية في جوهره، ليتحول إلى الوجهة السياحية الثقافية الأكثر ديناميكية في العالم بحلول عام 2030.\n•	العلا، وقد قُدم نحو 25 مليون دولار لتنمية السكان الأصليين للنمور العربية المهددة بالانقراض، كما سيشهد برنامج شامل لإعادة التوطين والحماية إطلاق 650 غزالاً عربياً و550 غزالاً رملياً في الصحراء القديمة هذا العام.\n•	مشروع البحر الأحمر، وهو مشروع سياحي فاخر متجدد سيكون له تأثير إيجابي على بيئة البحر الأحمر، ليخلق نظاماً بيئياً أنظف وأكثر اخضراراً، علماً أن الأهداف الخضراء تتضمن تشغيل الطاقة المتجددة بنسبة 100 في المئة، وتنفيذ مجموعة من السياسات بما في ذلك عدم وجود نفايات في المكب، وحيادية الكربون بنسبة 100 في المئة، وفرض حظر كامل على المواد البلاستيكية التي تستخدم مرة واحدة، وهناك أيضاً خطط لأن يصبح البحر الأحمر أكبر محمية سماء مظلمة معتمدة.\n•	تشكل الجبال في منطقة عسير الباردة والمورقة والخضراء نقطة محورية في حملة «إعادة التفكير في الصيف» المستمرة، وتتميز الجبال المغطاة بأشجار العرعر بقمم ثلجية يبلغ ارتفاعها أكثر من ثلاثة آلاف متر.\n•	الأحساء المدرجة في قائمة اليونسكو تستهدف تنمية السياحة المستدامة، ومع 2.5 مليون نخلة، فهي أكبر واحة في العالم.\n•	فوهة الوعبة، إحدى عجائب الدنيا الطبيعية، وهي تكوين طبيعي من المحتمل أن يكون نتيجة ثوران بركاني.\n•	الحجر المدرج في قائمة اليونسكو هو موقع رئيسي ومحمي بشكل جيد من الحضارة النبطية، ويتميز بمقابر ضخمة ذات واجهات مزخرفة تعود إلى القرن الأول قبل الميلاد إلى القرن الأول الميلادي، ونحو 50 نقشاً من فترة ما قبل النبطية ورسومات الكهوف.\n•	حائل، تتمتع بمناظر طبيعية لا تصدق من جبال الحجر الرملي التي شكلتها قرون من التعرية إلى البراكين البيضاء في حارة بني راشد وجبال شمر. \n\nمن الآن حتى عام تحقيق الرؤية 2030، تمتلك المملكة جدولاً مزدحماً وقائمة طويلة من المشاريع التي ينبغي تحقيقها، وستنتشر الحدائق الجيولوجية كجزء من السياحة الجيولوجية في المملكة، وخاصة في نيوم، والعلا، والرياض، ومنطقة البحر الأحمر، وجنوب غرب المملكة.\n',
    );
  }

  @override
  Widget build(BuildContext context) {
    return MapShell(
      title: 'السياحة والآثار',
      onBriefPressed: _showIntroBrief,
      briefButtonText: 'مقدمة',
      initialStyleAsset: 'assets/maps/saudi_geo/sahel.json',
      onMapCreated: (c) {
        _mapController = c;
        _loadMarkers(c);
      },
      sidebarContent: Column(
        children: _regionNames.map((regionName) {
          final isExpanded = _expandedRegion == regionName;
          final regionLandmarks =
              _landmarks.where((l) => l.region == regionName).toList();

          return Column(
            children: [
              CustomButton(
                text: regionName,
                styleType: ButtonStyleType.mainMenu,
                onPressed: () {
                  setState(() {
                    if (_expandedRegion == regionName) {
                      _expandedRegion = null;
                    } else {
                      _expandedRegion = regionName;
                      if (regionLandmarks.isNotEmpty &&
                          _mapController != null) {
                        final firstValid = regionLandmarks.firstWhere(
                          (l) => l.latitude > 0.0 && l.longitude > 0.0,
                          orElse: () => regionLandmarks.first,
                        );
                        if (firstValid.latitude > 0.0 &&
                            firstValid.longitude > 0.0) {
                          _mapController!.flyTo(
                            latitude: firstValid.latitude,
                            longitude: firstValid.longitude,
                            zoom: 7.0,
                          );
                        }
                      }
                    }
                  });
                  if (_mapController != null) {
                    _loadMarkers(_mapController!);
                  }
                },
              ),
              if (isExpanded)
                ...regionLandmarks.map(
                  (landmark) => CustomButton(
                    text: landmark.title,
                    styleType: ButtonStyleType.subMenu,
                    onPressed: () => _showLandmark(landmark),
                  ),
                ),
            ],
          );
        }).toList(),
      ),
    );
  }
}
